window.GRILE_QUESTION_SHARDS=window.GRILE_QUESTION_SHARDS||{};window.GRILE_QUESTION_SHARDS["shard-140"]=[{"id":"set2-FMCE9vtQ","fingerprint":"796b5f78e3e92235","chapterId":"set-2","subchapterId":"set2-7.08","type":"CM","text":"Care dintre următoarele investigații biologice de rutină sunt considerate obligatorii în evaluarea preextracțională?","options":[{"id":"A","text":"Hemoglobină, hematocrit și număr de leucocite"},{"id":"B","text":"Uree, creatinină și transaminaze serice (ALT, AST)"},{"id":"C","text":"Viteza de sedimentare a hematiilor (VSH)"},{"id":"D","text":"Glicemie sau hemoglobină glicozilată"},{"id":"E","text":"Timpul de sângerare și timpul de coagulare"}],"correct":["A","B","D"],"pages":[581],"source":"set-2"},{"id":"set2-6Nobtisl","fingerprint":"63808476362aefba","chapterId":"set-2","subchapterId":"set2-7.08","type":"CM","text":"Ce factori sunt implicați în producerea accidentelor în timpul extracției dentare?","options":[{"id":"A","text":"Nerespectarea de către pacient a indicațiilor postextracționale"},{"id":"B","text":"Vârsta înaintată a pacientului, ca factor independent"},{"id":"C","text":"Existența unor leziuni patologice preexistente"},{"id":"D","text":"Particularitățile morfologice ale dintelui ce urmează a fi extras și ale structurilor de vecinătate"},{"id":"E","text":"Greșeli de tehnică prin folosirea unor instrumente sau manopere neadecvate"}],"correct":["C","D","E"],"pages":[581],"source":"set-2"},{"id":"set2-BMeUqZP9","fingerprint":"cbc2736853829615","chapterId":"set-2","subchapterId":"set2-7.08","type":"CM","text":"Care dintre următoarele entități sunt clasificate ca accidente ale extracției dentare?","options":[{"id":"A","text":"Alveolita uscată postextracțională"},{"id":"B","text":"Împingerea dinților în spațiile perimaxilare"},{"id":"C","text":"Luxația articulației temporo-mandibulare (ATM)"},{"id":"D","text":"Hemoragia postextracțională tardivă"},{"id":"E","text":"Leziuni nervoase"}],"correct":["B","C","E"],"pages":[581],"source":"set-2"},{"id":"set2--TmWukYI","fingerprint":"74101f186ce1ed90","chapterId":"set-2","subchapterId":"set2-7.08","type":"CM","text":"Care este o măsură esențială pentru a reduce la minimum riscul de accidente și complicații în extracția dentară?","options":[{"id":"A","text":"Efectuarea unei evaluări corecte clinice și radiologice preextracționale."},{"id":"B","text":"Limitarea utilizării anestezicelor cu vasoconstrictor."},{"id":"C","text":"Utilizarea sistematică a tehnicii de extracție prin alveolotomie."},{"id":"D","text":"Administrarea profilactică de antibiotice cu spectru larg la toți pacienții."},{"id":"E","text":"Respectarea principiilor de extracție în corelație cu statusul local și general."}],"correct":["A","E"],"pages":[581],"source":"set-2"},{"id":"set2-5ou5iUa2","fingerprint":"e5717a30e1cd4971","chapterId":"set-2","subchapterId":"set2-7.08","type":"CM","text":"Care dintre următoarele situații reprezintă factori favorizanți pentru fractura coronară a dintelui în curs de extracție?","options":[{"id":"A","text":"Aplicarea unei prize incorecte a cleștelui de extracție."},{"id":"B","text":"Manevre brutale efectuate în cursul luxării dintelui."},{"id":"C","text":"Prezența unor obturații voluminoase la nivelul dintelui."},{"id":"D","text":"Fenomene de hipercementoză la nivel radicular."},{"id":"E","text":"Rădăcini curbe, cudate sau în „baionetă”."}],"correct":["A","B","C"],"pages":[582],"source":"set-2"},{"id":"set2-_mw59V-p","fingerprint":"7e45ee5004902c88","chapterId":"set-2","subchapterId":"set2-7.08","type":"CS","text":"Ce conduită terapeutică se impune imediat după producerea unei fracturi coronare a dintelui de extras?","options":[{"id":"A","text":"Se suturează plaga și se lasă resturile radiculare pentru a fi eliminate spontan."},{"id":"B","text":"Se realizează o radiografie și se temporizează extracția resturilor radiculare."},{"id":"C","text":"Pacientul este informat și se procedează la extracția resturilor radiculare."},{"id":"D","text":"Se imobilizează fragmentul coronar și se monitorizează vitalitatea dintelui."},{"id":"E","text":"Se aplică un pansament calmant și se reprogramează pacientul."}],"correct":["C"],"pages":[582],"source":"set-2"},{"id":"set2-MYcgmB-Z","fingerprint":"af73a69ea005764a","chapterId":"set-2","subchapterId":"set2-7.08","type":"CM","text":"Care dintre următorii factori sunt asociați cu un risc crescut de fractură radiculară în timpul extracției dentare?","options":[{"id":"A","text":"Rădăcini subțiri și efilate."},{"id":"B","text":"Prezența unor obturații voluminoase."},{"id":"C","text":"Carii de colet extinse."},{"id":"D","text":"Rădăcini divergente, în special la primii molari superiori."},{"id":"E","text":"Anchiloza dento-alveolară."}],"correct":["A","D","E"],"pages":[582],"source":"set-2"},{"id":"set2-8dLfKUvK","fingerprint":"798e3534f79cee55","chapterId":"set-2","subchapterId":"set2-7.08","type":"CS","text":"Ce eroare în manevrarea instrumentarului de extracție poate conduce la luxația dintelui vecin?","options":[{"id":"A","text":"Aplicarea incorectă a cleștelui în afara axului dintelui de extras."},{"id":"B","text":"Aplicarea unor forțe de tracțiune verticală necontrolată asupra cleștelui."},{"id":"C","text":"Utilizarea elevatorului cu punct de sprijin pe alveola dentară."},{"id":"D","text":"Sprijinirea elevatorului pe dintele vecin în loc de alveola dentară."},{"id":"E","text":"Aplicarea prea profundă a fălcilor cleștelui pe un dinte temporar."}],"correct":["D"],"pages":[582],"source":"set-2"},{"id":"set2-Ep_NzhgC","fingerprint":"1e15bd00ce18fee4","chapterId":"set-2","subchapterId":"set2-7.08","type":"CS","text":"Care este atitudinea terapeutică recomandată în cazul unei luxații cu mobilitate redusă a unui dinte vecin, produsă în timpul unei extracții?","options":[{"id":"A","text":"Repoziționarea și imobilizarea rigidă pentru 6-8 săptămâni."},{"id":"B","text":"Monitorizarea vitalității pulpare a dintelui afectat."},{"id":"C","text":"Replantarea imediată a dintelui vecin."},{"id":"D","text":"Devitalizarea de urgență a dintelui vecin."},{"id":"E","text":"Extracția profilactică a dintelui vecin."}],"correct":["B"],"pages":[582],"source":"set-2"},{"id":"set2-eGStaiL-","fingerprint":"a0cc58c3ec40327a","chapterId":"set-2","subchapterId":"set2-7.08","type":"CS","text":"Fractura coronară a dinților antagoniști este un accident care apare cel mai frecvent în timpul extracției dinților inferiori. Care este cauza principală a acestui accident?","options":[{"id":"A","text":"Utilizarea unui clește cu fălcile neadaptate la conturul dintelui."},{"id":"B","text":"Deraparea elevatorului în timpul luxării."},{"id":"C","text":"Prezența unor procese carioase extinse la nivelul dinților antagoniști."},{"id":"D","text":"Sprijinirea cleștelui pe dinții antagoniști în timpul manevrelor."},{"id":"E","text":"Aplicarea unor forțe de tracțiune verticală necontrolată asupra cleștelui."}],"correct":["E"],"pages":[582],"source":"set-2"},{"id":"set2-m8YH1nm-","fingerprint":"5f05987af5ffb267","chapterId":"set-2","subchapterId":"set2-7.08","type":"CS","text":"În ce situație particulară se înregistrează o frecvență relativ mare a extracției unui alt dinte decât cel vizat?","options":[{"id":"A","text":"În cazul extracțiilor dirijate în scop ortodontic."},{"id":"B","text":"În cazul pacienților cu anchiloză dento-alveolară."},{"id":"C","text":"În cazul extracțiilor molarilor temporari la copii."},{"id":"D","text":"În cazul extracțiilor dinților frontali superiori."},{"id":"E","text":"În cazul dinților cu distrucții corono-radiculare masive."}],"correct":["A"],"pages":[582],"source":"set-2"},{"id":"set2-jPJ3rE4M","fingerprint":"380b1d8b5e872bf3","chapterId":"set-2","subchapterId":"set2-7.08","type":"CM","text":"Care dintre următoarele reprezintă măsuri de prevenție pentru lezarea mugurilor dinților permanenți în timpul extracției molarilor temporari?","options":[{"id":"A","text":"Aplicarea fălcilor cleștelui cât mai apical posibil pentru o priză sigură."},{"id":"B","text":"Utilizarea unui clește cu fălci mai late pentru a distribui presiunea."},{"id":"C","text":"Recurgerea la extracția cu separație radiculară dacă rădăcinile temporare înconjoară coroana dintelui permanent."},{"id":"D","text":"Evitarea pătrunderii în profunzime cu elevatorul."},{"id":"E","text":"Realizarea obligatorie a unei evaluări radiologice preextracționale."}],"correct":["C","D","E"],"pages":[582],"source":"set-2"},{"id":"set2-gYQz2Y3W","fingerprint":"51d306855c93736a","chapterId":"set-2","subchapterId":"set2-7.08","type":"CS","text":"Ce măsură preextracțională este obligatorie în cazul extracției molarilor temporari ale căror rădăcini par să înconjoare coroana dintelui permanent subiacent?","options":[{"id":"A","text":"Utilizarea unui elevator în profunzime pentru luxarea dintelui."},{"id":"B","text":"Aplicarea profundă a fălcilor cleștelui pentru o priză mai bună."},{"id":"C","text":"O evaluare radiologică."},{"id":"D","text":"Se va recurge întotdeauna la extracția cu separație radiculară, fără a fi necesară o evaluare suplimentară."},{"id":"E","text":"Extracția prin alveolotomie de la început."}],"correct":["C"],"pages":[583],"source":"set-2"},{"id":"set2-OIjOnZyM","fingerprint":"e8e0ff53f138ab46","chapterId":"set-2","subchapterId":"set2-7.08","type":"CS","text":"Care este principala cauză a apariției leziunilor părților moi din cavitatea orală în timpul extracției dentare?","options":[{"id":"A","text":"Prezența unei infecții periapicale acute."},{"id":"B","text":"Utilizarea unor instrumente neadecvate."},{"id":"C","text":"Folosirea unor forțe excesive și necontrolate."},{"id":"D","text":"Anatomia particulară a pacientului."},{"id":"E","text":"Resorbția insuficientă a rădăcinilor dinților temporari."}],"correct":["C"],"pages":[583],"source":"set-2"},{"id":"set2-8qg3r9o9","fingerprint":"e72bda60460d417b","chapterId":"set-2","subchapterId":"set2-7.08","type":"CM","text":"Care dintre următoarele afirmații despre leziunile părților moi perimaxilare sunt corecte?","options":[{"id":"A","text":"Plăgile gingivale liniare sunt tratate exclusiv prin excizia fragmentelor de mucoasă, indiferent de viabilitatea lor."},{"id":"B","text":"Plăgile limbii produse prin deraparea elevatoarelor nu necesită sutură, hemostaza prin tamponament fiind eficientă."},{"id":"C","text":"Plăgile mucoasei palatine pot cauza hemoragie în jet dacă este lezată artera palatină, necesitând ligaturarea vasului."},{"id":"D","text":"În cazul decolărilor osoase importante, osul alveolar descoperit trebuie lăsat neacoperit pentru a se vindeca per secundam."},{"id":"E","text":"Plăgile planșeului bucal pot duce la hematoame disecante, cu risc de asfixie prin obstrucția căilor aeriene superioare."}],"correct":["C","E"],"pages":[583],"source":"set-2"},{"id":"set2-qESCG_fO","fingerprint":"da94ef0b36daf2a4","chapterId":"set-2","subchapterId":"set2-7.08","type":"CS","text":"Ce atitudine terapeutică este indicată în cazul unei fracturi complete a procesului alveolar, unde fragmentul osos este detașat de periost?","options":[{"id":"A","text":"Se aplică o meșă iodoformată peste fragment, fără a se interveni chirurgical."},{"id":"B","text":"Se lasă fragmentul osos in situ pentru a acționa ca un grefon autolog."},{"id":"C","text":"Se repoziționează fragmentul și se suturează plaga, contând pe vascularizația endo-osoasă."},{"id":"D","text":"Se imobilizează fragmentul cu o miniplăcuță de titan."},{"id":"E","text":"Se îndepărtează fragmentul osos, se regularizează marginile osoase și se suturează plaga."}],"correct":["E"],"pages":[583],"source":"set-2"},{"id":"set2-IQS3a55B","fingerprint":"a0f600c904e31b94","chapterId":"set-2","subchapterId":"set2-7.08","type":"CM","text":"Care dintre următoarele complicații pot fi asociate cu fractura corticalei linguale în timpul extracției molarilor inferiori?","options":[{"id":"A","text":"Fractura tuberozității maxilare."},{"id":"B","text":"Lezarea arterei palatine."},{"id":"C","text":"Lezarea nervului lingual."},{"id":"D","text":"Deschiderea sinusului maxilar."},{"id":"E","text":"Împingerea dintelui în planșeul oral."}],"correct":["C","E"],"pages":[583],"source":"set-2"},{"id":"set2-bFxYY9ge","fingerprint":"a723b3e1eac587f3","chapterId":"set-2","subchapterId":"set2-7.08","type":"CS","text":"În timpul extracției cărui dinte survine cel mai frecvent fractura tuberozității maxilare?","options":[{"id":"A","text":"Molarul de minte superior."},{"id":"B","text":"Caninul superior."},{"id":"C","text":"Primul premolar superior."},{"id":"D","text":"Molarul doi superior, când molarul trei este prezent."},{"id":"E","text":"Molarul doi inferior."}],"correct":["A"],"pages":[583],"source":"set-2"},{"id":"set2-L9YpsKL5","fingerprint":"0fb6a3b9612fb8d9","chapterId":"set-2","subchapterId":"set2-7.08","type":"CS","text":"Care este atitudinea corectă în cazul unui fragment osos alveolar fracturat care nu este deperiostat?","options":[{"id":"A","text":"Se repoziționează și se suturează cu atenție plaga."},{"id":"B","text":"Se excizează periostul și apoi se îndepărtează fragmentul osos."},{"id":"C","text":"Se acoperă cu o meșă iodoformată, fără repoziționare."},{"id":"D","text":"Se lasă nesuturat pentru a permite drenajul."},{"id":"E","text":"Se îndepărtează obligatoriu pentru a preveni infecția."}],"correct":["A"],"pages":[583],"source":"set-2"},{"id":"set2-i7qx7_BG","fingerprint":"fc2ce6eba62c842d","chapterId":"set-2","subchapterId":"set2-7.08","type":"CS","text":"Ce măsuri de urgență sunt necesare în cazul apariției unui hematom disecant de limbă și planșeu bucal?","options":[{"id":"A","text":"Sutura în masă a plăgii în cabinetul stomatologic."},{"id":"B","text":"Asigurarea permeabilității căilor aeriene superioare și trimiterea de urgență la chirurgie OMF."},{"id":"C","text":"Realizarea unei hemostaze eficiente prin tamponament local."},{"id":"D","text":"Aplicarea de comprese reci pentru a limita extinderea hematomului."},{"id":"E","text":"Administrarea de antibiotice cu spectru larg și monitorizare ambulatorie."}],"correct":["B"],"pages":[583],"source":"set-2"},{"id":"set2-8ocyWqmR","fingerprint":"0f1159938e8513d7","chapterId":"set-2","subchapterId":"set2-7.08","type":"CM","text":"Care sunt complicațiile posibile asociate cu o fractură a tuberozității maxilare?","options":[{"id":"A","text":"Împingerea molarului de minte superior în spațiul infratemporal."},{"id":"B","text":"Formarea unui hematom care se poate infecta secundar."},{"id":"C","text":"Producerea de comunicări oro-sinusale largi."},{"id":"D","text":"Lezarea plexului venos perituberozitar, cu hemoragie consecutivă."},{"id":"E","text":"Fractura unghiului mandibular."}],"correct":["B","C","D"],"pages":[584],"source":"set-2"},{"id":"set2-9nKNtljM","fingerprint":"498c021c55a1ace7","chapterId":"set-2","subchapterId":"set2-7.08","type":"CS","text":"În cazul unei fracturi de tuberozitate maxilară în care fragmentul osos este complet detașat și separat de periost, care este atitudinea terapeutică corectă?","options":[{"id":"A","text":"Se reașează tuberozitatea împreună cu dintele extras și se monitorizează timp de 6-8 săptămâni."},{"id":"B","text":"Se îndepărtează fragmentul și se realizează sutura primară a mucoasei acoperitoare."},{"id":"C","text":"Se practică imediat cura radicală de sinus pentru a preveni sinuzita maxilară."},{"id":"D","text":"Se menține fragmentul osos și se iau măsuri pentru reintegrarea sa osoasă."},{"id":"E","text":"Se imobilizează de urgență fractura și se trimite pacientul la chirurgie OMF."}],"correct":["B"],"pages":[584],"source":"set-2"},{"id":"set2-uzXJ2dQH","fingerprint":"e796531633f5bee7","chapterId":"set-2","subchapterId":"set2-7.08","type":"CM","text":"Care dintre următoarele elemente reprezintă factori de risc pentru producerea unei fracturi de mandibulă în timpul extracției molarului de minte inferior?","options":[{"id":"A","text":"Atrofia accentuată a mandibulei."},{"id":"B","text":"Rădăcinile drepte ale molarului de minte inferior."},{"id":"C","text":"Incluzia profundă a molarului de minte inferior."},{"id":"D","text":"Prezența unor procese patologice precum chistul folicular."},{"id":"E","text":"Procese resorbtive periradiculare la nivelul premolarilor superiori."}],"correct":["A","C","D"],"pages":[584],"source":"set-2"},{"id":"set2-_GTv0dZ5","fingerprint":"40294c433e9f8b79","chapterId":"set-2","subchapterId":"set2-7.08","type":"CS","text":"De ce este contraindicată utilizarea elevatorului Lecluse pentru extracția unui molar de minte inferior cu rădăcini drepte?","options":[{"id":"A","text":"Poate favoriza producerea unei fracturi de unghi mandibular."},{"id":"B","text":"Produce frecvent smulgerea tuberozității maxilare."},{"id":"C","text":"Favorizează deschiderea sinusului maxilar."},{"id":"D","text":"Crește riscul de lezare a plexului venos perituberozitar."},{"id":"E","text":"Poate împinge dintele în spațiul pterigomaxilar."}],"correct":["A"],"pages":[584],"source":"set-2"},{"id":"set2-FRIEaSfe","fingerprint":"8bee9b9a1fd1a217","chapterId":"set-2","subchapterId":"set2-7.08","type":"CM","text":"Care sunt afirmațiile corecte referitoare la împingerea molarului de minte superior în spațiul pterigomaxilar?","options":[{"id":"A","text":"Îndepărtarea dintelui este întotdeauna posibilă imediat după producerea accidentului."},{"id":"B","text":"Există riscul unor complicații septice severe, precum flegmonul hemifacial."},{"id":"C","text":"Se produce exclusiv în timpul extracției molarului de minte inferior."},{"id":"D","text":"Dintele se poate situa medial de ramul mandibular, producând tulburări ale deschiderii cavității orale."},{"id":"E","text":"Accidentul se poate asocia frecvent cu fractura tuberozității maxilare."}],"correct":["B","D","E"],"pages":[584],"source":"set-2"},{"id":"set2-gXFu_0yE","fingerprint":"98e0997802dd2758","chapterId":"set-2","subchapterId":"set2-7.08","type":"CS","text":"Ce factor poate împiedica rezolvarea imediată a împingerii unui molar de minte superior în părțile moi profunde?","options":[{"id":"A","text":"Dezvoltarea semnelor de sinuzită maxilară acută."},{"id":"B","text":"Prezența unei comunicări oro-sinusale largi."},{"id":"C","text":"Fragmentul osos este încă atașat de periost."},{"id":"D","text":"Hemoragia datorată lezării plexului venos pterigoidian."},{"id":"E","text":"Necesitatea de a reduce și imobiliza o fractură de mandibulă."}],"correct":["D"],"pages":[584],"source":"set-2"},{"id":"set2-aptfc_LB","fingerprint":"562b7df71b15e8d1","chapterId":"set-2","subchapterId":"set2-7.08","type":"CS","text":"Ce mecanism poate duce la împingerea molarului de minte superior în spațiul infratemporal?","options":[{"id":"A","text":"Aplicarea unor forțe exagerate, necontrolate, cu elevatorul."},{"id":"B","text":"Prezența unor procese resorbtive periradiculare."},{"id":"C","text":"Prezența unui chist folicular la nivelul maxilarului."},{"id":"D","text":"Utilizarea elevatorului Lecluse pe rădăcini drepte."},{"id":"E","text":"Atrofia accentuată a mandibulei."}],"correct":["A"],"pages":[584],"source":"set-2"},{"id":"set2-o34mMdE4","fingerprint":"4fb44c36d7819466","chapterId":"set-2","subchapterId":"set2-7.08","type":"CM","text":"Care sunt factorii care pot conduce la împingerea molarului trei inferior în planșeul bucal în timpul extracției?","options":[{"id":"A","text":"Prezența unei corticale linguale foarte subțiri sau absente."},{"id":"B","text":"Prezența unui pachet vascular-nervos în proximitatea apexurilor dentare."},{"id":"C","text":"Situarea molarului deasupra mușchiului milohioidian."},{"id":"D","text":"Aplicarea unor forțe exagerate cu elevatorul în direcție posterioară și linguală."},{"id":"E","text":"Utilizarea unei căi de abord cutanate pentru extracție."}],"correct":["A","D"],"pages":[585],"source":"set-2"},{"id":"set2-RNpOZdBj","fingerprint":"580328565e098d37","chapterId":"set-2","subchapterId":"set2-7.08","type":"CS","text":"Ce cale de abord chirurgical se utilizează pentru un molar de minte inferior care a fost împins în părțile moi, deasupra mușchiului milohioidian?","options":[{"id":"A","text":"O cale de abord combinată, orală și cutanată."},{"id":"B","text":"Nu se intervine chirurgical, se optează pentru monitorizare."},{"id":"C","text":"Se utilizează exclusiv navigația chirurgicală pentru extracție."},{"id":"D","text":"O cale de abord orală."},{"id":"E","text":"O cale de abord cutanată."}],"correct":["D"],"pages":[585],"source":"set-2"},{"id":"set2-X9WlrsOJ","fingerprint":"a0c583dbbc5dfc96","chapterId":"set-2","subchapterId":"set2-7.08","type":"CM","text":"Referitor la navigația chirurgicală utilizată pentru localizarea unui dinte în spațiile perimaxilare, care dintre următoarele afirmații sunt adevărate?","options":[{"id":"A","text":"Este un concept din cadrul chirurgiei asistate de computer."},{"id":"B","text":"Permite reducerea timpului de intervenție și a riscului de lezare a structurilor anatomice."},{"id":"C","text":"Necesită realizarea unui model virtual al regiunii pe baza unui CT preoperator."},{"id":"D","text":"Folosește un sistem computerizat de localizare tridimensională bazat pe raze X intraoperator."},{"id":"E","text":"Este aplicabilă doar pentru dinții situați sub mușchiul milohioidian."}],"correct":["A","B","C"],"pages":[585],"source":"set-2"},{"id":"set2-ASoPkHXs","fingerprint":"3a5948523b49324d","chapterId":"set-2","subchapterId":"set2-7.08","type":"CS","text":"Care este consecința secționării nervului mentonier în timpul extracției prin alveolotomie a unui premolar inferior?","options":[{"id":"A","text":"Recuperarea sensibilității în decurs de câteva săptămâni."},{"id":"B","text":"Modificări gustative."},{"id":"C","text":"Recuperare funcțională spontană în 6-9 luni."},{"id":"D","text":"Anestezie definitivă."},{"id":"E","text":"O parestezie tranzitorie care se remite fără tratament în 87% din cazuri."}],"correct":["D"],"pages":[585],"source":"set-2"},{"id":"set2-rVwx6I5W","fingerprint":"91aec69876e8fcdf","chapterId":"set-2","subchapterId":"set2-7.08","type":"CS","text":"Care este probabilitatea de remitere a tulburărilor fără tratament pentru pacienții cu leziuni ale nervului alveolar inferior, respectiv ale nervului lingual, în urma extracției molarilor de minte?","options":[{"id":"A","text":"96% pentru nervul alveolar inferior și 87% pentru nervul lingual."},{"id":"B","text":"Peste 95% pentru ambele tipuri de leziuni nervoase."},{"id":"C","text":"87% pentru nervul alveolar inferior și 96% pentru nervul lingual."},{"id":"D","text":"Între 0,6% și 5% pentru ambele tipuri de leziuni."},{"id":"E","text":"Sub 50% pentru ambele tipuri, necesitând frecvent intervenție microchirurgicală."}],"correct":["A"],"pages":[585],"source":"set-2"},{"id":"set2-tzcSMFS9","fingerprint":"0cb2811a31531be0","chapterId":"set-2","subchapterId":"set2-7.08","type":"CS","text":"Ce factor favorizează recuperarea funcțională bună a nervului alveolar inferior după o leziune?","options":[{"id":"A","text":"Absența unui pachet vascular adiacent."},{"id":"B","text":"Faptul că nervul este reținut în interiorul unui canal osos."},{"id":"C","text":"Variabilitatea sa anatomică redusă comparativ cu nervul lingual."},{"id":"D","text":"Intervalul scurt de recuperare, de obicei sub 4 săptămâni."},{"id":"E","text":"Rata sa de lezare, care este mult mai mică decât a nervului lingual."}],"correct":["B"],"pages":[585],"source":"set-2"},{"id":"set2-2j5VcecF","fingerprint":"601180c6d572cb05","chapterId":"set-2","subchapterId":"set2-7.08","type":"CM","text":"În comparație cu lezarea nervului alveolar inferior, cum se caracterizează lezarea nervului lingual în timpul extracției molarilor inferiori?","options":[{"id":"A","text":"Are o probabilitate de recuperare spontană mult mai mică."},{"id":"B","text":"Apare mult mai rar."},{"id":"C","text":"Presupune modificări gustative, afectând într-o mai mare măsură pacienții."},{"id":"D","text":"Are o rată de recuperare spontană de 96%."},{"id":"E","text":"Este cauzată exclusiv de trecerea nervului prin trigonul retromolar."}],"correct":["A","B","C"],"pages":[585],"source":"set-2"},{"id":"set2-un0xB0ez","fingerprint":"6bc0cd2e967f2368","chapterId":"set-2","subchapterId":"set2-7.08","type":"CM","text":"Ce măsuri tehnice sunt indicate pentru a reduce incidența lezării nervului lingual în timpul extracției molarului trei inferior?","options":[{"id":"A","text":"Chiuretajul intempestiv al versantului lingual al alveolei."},{"id":"B","text":"Decolarea brutală a sacului folicular de pe versantul lingual al alveolei."},{"id":"C","text":"Efectuarea trepanării osoase cu precădere la nivelul corticalei osoase vestibulare."},{"id":"D","text":"Secționarea dintelui, dacă este necesar, pentru a facilita extracția acestuia."},{"id":"E","text":"Evitarea rezecției corticalei linguale."}],"correct":["C","D","E"],"pages":[585],"source":"set-2"},{"id":"set2-hPiwqWvY","fingerprint":"77ae03fc695a3649","chapterId":"set-2","subchapterId":"set2-7.08","type":"CM","text":"Care dintre următoarele manevre sunt recomandate pentru a reduce incidența lezării nervului lingual în timpul extracției molarului trei inferior?","options":[{"id":"A","text":"Rezecția corticalei osoase linguale pentru a îmbunătăți vizibilitatea."},{"id":"B","text":"Perforarea controlată a corticalei linguale cu instrumentar rotativ pentru a facilita luxația."},{"id":"C","text":"Trepanarea osoasă efectuată predominant la nivelul corticalei osoase vestibulare."},{"id":"D","text":"Secționarea dintelui, dacă este necesar, pentru a facilita extracția acestuia."},{"id":"E","text":"Plasarea de suturi profunde în lamboul lingual pentru a asigura o hemostază eficientă."}],"correct":["C","D"],"pages":[586],"source":"set-2"},{"id":"set2-APO6cxdl","fingerprint":"254444e1c3d3a251","chapterId":"set-2","subchapterId":"set2-7.08","type":"CS","text":"Care este o caracteristică a lezării nervului nazopalatin în timpul odontectomiei caninilor incluși?","options":[{"id":"A","text":"Recuperarea funcției senzitive apare de obicei destul de repede."},{"id":"B","text":"Determină sechele neurologice permanente și severe."},{"id":"C","text":"Zona de inervație senzitivă afectată este extinsă."},{"id":"D","text":"Necesită întotdeauna o intervenție de microchirurgie reparatorie."},{"id":"E","text":"Este o complicație specifică extracției molarilor inferiori."}],"correct":["A"],"pages":[586],"source":"set-2"},{"id":"set2-Uxkn2cUE","fingerprint":"a3c6ad9291ae55e7","chapterId":"set-2","subchapterId":"set2-7.08","type":"CS","text":"Un pacient prezintă durere intensă la nivelul articulației temporomandibulare și imposibilitatea de a închide gura imediat după o extracție de molar inferior. Care este cel mai probabil accident intraoperator?","options":[{"id":"A","text":"Luxația articulației temporomandibulare (ATM)."},{"id":"B","text":"Trismus postextracțional."},{"id":"C","text":"Lezarea nervului lingual."},{"id":"D","text":"Fracturarea unui instrument."},{"id":"E","text":"Hemoragie postextracțională precoce."}],"correct":["A"],"pages":[586],"source":"set-2"},{"id":"set2--qWjBf2N","fingerprint":"ca41289950bc30f3","chapterId":"set-2","subchapterId":"set2-7.08","type":"CS","text":"Ce factor crește riscul de înghițire sau aspirare a fragmentelor dentare sau osoase în timpul unei extracții dentare?","options":[{"id":"A","text":"Secționarea dintelui în timpul extracției."},{"id":"B","text":"Poziția pacientului în fotoliul dentar apropiată de clinostatism."},{"id":"C","text":"Efectuarea unei alveolotomii."},{"id":"D","text":"Utilizarea anesteziei cu vasoconstrictor."},{"id":"E","text":"Apariția trismusului postoperator."}],"correct":["B"],"pages":[586],"source":"set-2"},{"id":"set2-p8geE_17","fingerprint":"4cf2cc96bb8b723a","chapterId":"set-2","subchapterId":"set2-7.08","type":"CS","text":"Care este cauza principală a trismusului apărut după odontectomia molarilor de minte inferiori?","options":[{"id":"A","text":"Formarea unui cheag sanguin instabil în alveolă."},{"id":"B","text":"Contracția spastică a mușchiului pterigoidian intern."},{"id":"C","text":"Secționarea unor filete ale nervului lingual."},{"id":"D","text":"Lezarea directă a articulației temporomandibulare."},{"id":"E","text":"Edemul postextracțional la nivelul lamboului vestibular."}],"correct":["B"],"pages":[586],"source":"set-2"},{"id":"set2-6lIMCOXo","fingerprint":"9c985118335f69f6","chapterId":"set-2","subchapterId":"set2-7.08","type":"CS","text":"Ce tip de hemoragie postextracțională se definește ca sângerarea ce reapare la 2-3 ore de la extracție?","options":[{"id":"A","text":"Hemoragie imediat-prelungită."},{"id":"B","text":"Hemoragie primară."},{"id":"C","text":"Hemoragie secundară."},{"id":"D","text":"Hemoragie tardivă."},{"id":"E","text":"Hemoragie precoce."}],"correct":["E"],"pages":[586],"source":"set-2"},{"id":"set2-OPcc290w","fingerprint":"fb8636aa5f47228a","chapterId":"set-2","subchapterId":"set2-7.08","type":"CM","text":"Care dintre următorii sunt considerați factori locali ce pot favoriza hemoragiile postextracționale?","options":[{"id":"A","text":"Administrarea de antiinflamatoare nesteroidiene (AINS)."},{"id":"B","text":"Prezența unor eschile osoase în alveolă."},{"id":"C","text":"Tracțiunea exagerată a lambourilor cu depărtătoarele."},{"id":"D","text":"Vasodilatația secundară după anestezie cu vasoconstrictor."},{"id":"E","text":"Persistența țesutului de granulație în alveolă."}],"correct":["B","D","E"],"pages":[586],"source":"set-2"},{"id":"set2-CDJm_rPb","fingerprint":"5951248858e5dc5f","chapterId":"set-2","subchapterId":"set2-7.08","type":"CS","text":"Ce complicație postextracțională este favorizată în mod particular de extracțiile laborioase, alveolotomii și tracțiunea exagerată a lambourilor?","options":[{"id":"A","text":"Lezarea nervului nazopalatin."},{"id":"B","text":"Hemoragia tardivă."},{"id":"C","text":"Odinofagia."},{"id":"D","text":"Luxația ATM."},{"id":"E","text":"Edemul postextracțional."}],"correct":["E"],"pages":[586],"source":"set-2"},{"id":"set2-pslPpuwC","fingerprint":"82bdf592934c1015","chapterId":"set-2","subchapterId":"set2-7.08","type":"CM","text":"Care dintre următorii sunt considerați factori locali ce pot fi implicați în hemoragiile postextracționale?","options":[{"id":"A","text":"Persistența țesutului de granulație în alveolă."},{"id":"B","text":"Lezarea arterei alveolare inferioare."},{"id":"C","text":"Hipertensiunea arterială."},{"id":"D","text":"Vasodilatația secundară apărută în cazul anestezicelor cu vasoconstrictor."},{"id":"E","text":"Prezența unor eschile osoase sau resturi dentare în alveolă."}],"correct":["A","B","D","E"],"pages":[587],"source":"set-2"},{"id":"set2-EPMG-RvV","fingerprint":"682df3a7f137ab8b","chapterId":"set-2","subchapterId":"set2-7.08","type":"CM","text":"Care dintre următoarele afecțiuni sau stări sunt considerate factori generali care pot determina tulburări ale hemostazei?","options":[{"id":"A","text":"Tratamentele citostatice."},{"id":"B","text":"Plăgile mucoase întinse cu delabrări ale gingivomucoasei."},{"id":"C","text":"Insuficiența hepatică."},{"id":"D","text":"Vasculopatiile care cresc fragilitatea și permeabilitatea vasculară."},{"id":"E","text":"Fractura procesului alveolar."}],"correct":["A","C","D"],"pages":[587],"source":"set-2"},{"id":"set2-6rt7H3_m","fingerprint":"349d9b73d043cb51","chapterId":"set-2","subchapterId":"set2-7.08","type":"CS","text":"Conform anamnezei privind sângerările postoperatorii, ce durată a unei sângerări postextracționale ridică suspiciunea unei tulburări de hemostază?","options":[{"id":"A","text":"O sângerare abundentă în primele 2-3 ore, care se reduce ulterior."},{"id":"B","text":"O sângerare care a durat mai mult de 24 de ore și a necesitat îngrijiri medicale."},{"id":"C","text":"Orice sângerare care persistă mai mult de 6 ore."},{"id":"D","text":"O sângerare minoră care se oprește și reîncepe în primele 24 de ore."},{"id":"E","text":"O sângerare redusă care durează până la 12 ore."}],"correct":["B"],"pages":[587],"source":"set-2"},{"id":"set2-s6E5OPOA","fingerprint":"0a93d5696c85c9e6","chapterId":"set-2","subchapterId":"set2-7.08","type":"CM","text":"Care dintre următoarele substanțe sau clase de medicamente fac parte din grupul celor 5 “A” care influențează hemostaza?","options":[{"id":"A","text":"Anxiolitice."},{"id":"B","text":"Antihistaminice."},{"id":"C","text":"Aspirină."},{"id":"D","text":"Antitumorale (citostatice)."},{"id":"E","text":"Anticoagulante."}],"correct":["C","D","E"],"pages":[587],"source":"set-2"},{"id":"set2-yTCrr_cj","fingerprint":"8f7e431114bcee0b","chapterId":"set-2","subchapterId":"set2-7.08","type":"CM","text":"Ce măsuri sunt recomandate la pacienții cu risc crescut de sângerare în vederea unei extracții dentare?","options":[{"id":"A","text":"Realizarea prealabilă a unor gutiere conformatoare pentru a exercita compresie mecanică."},{"id":"B","text":"Pacientul poate pleca imediat după extracție dacă sângerarea pare a fi oprită."},{"id":"C","text":"Suturarea plăgii postextracționale și aplicarea unui pansament supraalveolar compresiv."},{"id":"D","text":"Administrarea unui antibiotic din grupul celor 5 “A” pentru a preveni infecția și sângerarea."},{"id":"E","text":"Realizarea extracției cât mai atraumatic posibil, fără sfacelizări ale părților moi."}],"correct":["A","C","E"],"pages":[587],"source":"set-2"},{"id":"set2-XlAA7I_F","fingerprint":"b58cbd07c472d6bb","chapterId":"set-2","subchapterId":"set2-7.08","type":"CS","text":"Care este metoda corectă de aplicare a trombinei, un agent hemostatic activ, în tratamentul local al hemoragiei postextracționale precoce?","options":[{"id":"A","text":"Se administrează intravenos pentru un efect hemostatic sistemic rapid."},{"id":"B","text":"Se dizolvă în 2 ml de ser fiziologic și lichidul obținut se injectează lent în alveolă."},{"id":"C","text":"Se amestecă cu un burete de gelatină și se introduce în alveolă."},{"id":"D","text":"Se îmbibă o meșă de tifon în soluția de trombină și se introduce forțat în alveolă."},{"id":"E","text":"Se aplică sub formă de pulbere direct în alveolă și se compresează."}],"correct":["B"],"pages":[587],"source":"set-2"},{"id":"set2-nTb77LTH","fingerprint":"2d841a5582134825","chapterId":"set-2","subchapterId":"set2-7.08","type":"CS","text":"Care dintre următoarele produse este un exemplu de agent hemostatic pasiv utilizat în tratamentul hemoragiei postextracționale?","options":[{"id":"A","text":"Heparina injectabilă."},{"id":"B","text":"Celuloza oxidată (Surgicel®)."},{"id":"C","text":"Aspirina."},{"id":"D","text":"Pulberea uscată de trombină."},{"id":"E","text":"Adezivul fibrinic."}],"correct":["B"],"pages":[587],"source":"set-2"},{"id":"set2-aQIFjaYo","fingerprint":"7f1afeccef1395f3","chapterId":"set-2","subchapterId":"set2-7.08","type":"CS","text":"Ce conduită este obligatorie în cazul unui pacient aflat în tratament cu anticoagulante orale care necesită o extracție dentară?","options":[{"id":"A","text":"Se solicită un consult interdisciplinar, iar medicul curant va decide întreruperea și eventuala înlocuire a tratamentului."},{"id":"B","text":"Se temporizează extracția pe o perioadă nedeterminată, deoarece riscul este prea mare."},{"id":"C","text":"Medicul stomatolog va indica pacientului să întrerupă tratamentul cu 24 de ore înainte de extracție."},{"id":"D","text":"Se efectuează extracția, urmată de aplicarea unui pansament compresiv puternic timp de 2 ore."},{"id":"E","text":"Se administrează un agent hemostatic activ, precum trombina, profilactic, înainte de extracție."}],"correct":["A"],"pages":[587],"source":"set-2"},{"id":"set2-h8z0jjRl","fingerprint":"e55ba792d6325f74","chapterId":"set-2","subchapterId":"set2-7.08","type":"CM","text":"Care sunt afirmațiile corecte referitoare la utilizarea analogilor de lizină în hemostaza postextracțională?","options":[{"id":"A","text":"Acidul tranexamic în soluție 5% poate fi utilizat pentru umectarea bureților hemostatici."},{"id":"B","text":"Acidul aminocaproic și acidul tranexamic protejează cheagul de acțiunea fibrinolitică a plasmei."},{"id":"C","text":"Soluția de acid tranexamic este indicată în special când structurile nervoase, precum nervul alveolar inferior, sunt expuse."},{"id":"D","text":"Acidul tranexamic se poate aplica doar intraalveolar, nu și pe pansamentul compresiv."},{"id":"E","text":"Acidul aminocaproic în soluție 5% se aplică prin imbibiția unei meșe sterile, menținută compresiv supraalveolar."}],"correct":["A","B"],"pages":[588],"source":"set-2"},{"id":"set2-fL_FHLhp","fingerprint":"39b6317f14911fa3","chapterId":"set-2","subchapterId":"set2-7.08","type":"CS","text":"Care este mecanismul de acțiune principal al Etamsilatului administrat pentru controlul hemoragiei?","options":[{"id":"A","text":"Se administrează exclusiv intravenos în hemoragiile grave."},{"id":"B","text":"Are un efect direct asupra factorilor plasmatici ai coagulării, potențându-i."},{"id":"C","text":"Produce o vasoconstricție locală puternică, similar cu cea a anestezicelor locale."},{"id":"D","text":"Inhibă procesul de fibrinoliză, stabilizând astfel cheagul sanguin."},{"id":"E","text":"Acționează asupra hemostazei primare prin favorizarea adezivității trombocitare și creșterea rezistenței capilare."}],"correct":["E"],"pages":[588],"source":"set-2"},{"id":"set2-CAB9KnlV","fingerprint":"bb29d8422dfd6532","chapterId":"set-2","subchapterId":"set2-7.08","type":"CM","text":"Care dintre următorii factori favorizează apariția complicațiilor infecțioase postextracționale?","options":[{"id":"A","text":"Absența eschilelor osoase în alveolă."},{"id":"B","text":"Extracția atraumatică, cu menținerea integrității gingivomucoasei."},{"id":"C","text":"Chiuretajul alveolar complet, cu îndepărtarea tuturor resturilor."},{"id":"D","text":"Utilizarea instrumentarului rotativ fără o răcire adecvată."},{"id":"E","text":"Efectuarea extracției în plin proces inflamator."}],"correct":["D","E"],"pages":[588],"source":"set-2"},{"id":"set2-EM-My9jk","fingerprint":"dc6368d4458bae12","chapterId":"set-2","subchapterId":"set2-7.08","type":"CS","text":"Cum trebuie gestionată o extracție dentară la un pacient cunoscut cu boala von Willebrand?","options":[{"id":"A","text":"Se administrează preventiv Etamsilat, care acționează pe factorii plasmatici deficitari."},{"id":"B","text":"Se amână extracția până la normalizarea spontană a parametrilor hemostazei."},{"id":"C","text":"Tratamentul de elecție este electrocoagularea țesuturilor sângerânde."},{"id":"D","text":"Se poate realiza în cabinetul stomatologic, cu sutura obligatorie a plăgii."},{"id":"E","text":"Se va realiza în secțiile de chirurgie oro-maxilo-facială, în condiții de spitalizare."}],"correct":["E"],"pages":[588],"source":"set-2"},{"id":"set2-r56e6vDZ","fingerprint":"1f2d609fe3fe9f48","chapterId":"set-2","subchapterId":"set2-7.08","type":"CM","text":"Care sunt caracteristicile alveolitei uscate („dry socket”)?","options":[{"id":"A","text":"Reprezintă o complicație cu o incidență de sub 0,1% după odontectomii."},{"id":"B","text":"Este cauzată de o organizare excesiv de rapidă a cheagului sanguin."},{"id":"C","text":"Mecanismul patologic principal este liza cheagului, datorată acțiunii fibrinolitice."},{"id":"D","text":"Apare cel mai frecvent la pacienții cu reactivitate imunitară redusă."},{"id":"E","text":"Culturile bacteriologice din alveolă indică prezența unei flore microbiene patogene specifice."}],"correct":["C","D"],"pages":[588],"source":"set-2"},{"id":"set2-xn5ymo2s","fingerprint":"6fee904b28c9c144","chapterId":"set-2","subchapterId":"set2-7.08","type":"CS","text":"Ce consecință principală poate avea aplicarea de substanțe caustice sau electrocoagularea pentru oprirea unei hemoragii postextracționale?","options":[{"id":"A","text":"Stimulează regenerarea țesuturilor moi din jurul alveolei."},{"id":"B","text":"Sunt recomandate în special la pacienții cu tulburări de coagulare."},{"id":"C","text":"Poate provoca necroză tisulară, cu reapariția sângerării."},{"id":"D","text":"Previn complicațiile infecțioase prin sterilizarea plăgii."},{"id":"E","text":"Asigură o hemostază rapidă și de lungă durată."}],"correct":["C"],"pages":[588],"source":"set-2"},{"id":"set2-u8MD2gqj","fingerprint":"4c89f38aed20f643","chapterId":"set-2","subchapterId":"set2-7.08","type":"CM","text":"Care dintre următoarele situații sunt considerate factori favorizanți pentru dezvoltarea alveolitei postextracționale?","options":[{"id":"A","text":"Pansamentul compresiv intraalveolar prelungit."},{"id":"B","text":"Activitate fibrinolitică crescută ce duce la absența cheagului."},{"id":"C","text":"Tulburări vasomotorii regionale datorate traumatismului operator și vasoconstrictorilor."},{"id":"D","text":"Extracții rapide și atraumatice."},{"id":"E","text":"Absența infecțiilor preexistente la nivelul dintelui extras."}],"correct":["A","B","C"],"pages":[588],"source":"set-2"},{"id":"set2-7koleqNJ","fingerprint":"35575c0060d36e6e","chapterId":"set-2","subchapterId":"set2-7.08","type":"CS","text":"Un pacient în vârstă dezvoltă o echimoză cervico-facială după o extracție laborioasă. Care este evoluția tipică și managementul acestei complicații?","options":[{"id":"A","text":"Implică obligatoriu explorarea chirurgicală pentru evacuarea colecției."},{"id":"B","text":"Se agravează progresiv, necesitând tratament hemostatic sistemic."},{"id":"C","text":"Este cauzată exclusiv de stări de fragilitate vasculară, indiferent de traumatismul operator."},{"id":"D","text":"Necesită întotdeauna antibioterapie pentru a preveni suprainfectarea."},{"id":"E","text":"Evoluția este de regulă favorabilă, cu remisie spontană în 5-7 zile."}],"correct":["E"],"pages":[588],"source":"set-2"},{"id":"set2-W6cf1Kf9","fingerprint":"e345c0ce0ff13907","chapterId":"set-2","subchapterId":"set2-7.08","type":"CM","text":"Care sunt caracteristicile clinice ale alveolitei uscate?","options":[{"id":"A","text":"Ameliorarea completă a durerii prin administrarea de antalgice uzuale."},{"id":"B","text":"Prezența adenitei regionale și a semnelor generale de infecție sistemică."},{"id":"C","text":"Existența unui cheag sanguin bine organizat care umple alveola."},{"id":"D","text":"Prezența pereților osoși uscați, fără tendință la sângerare, la nivelul alveolei."},{"id":"E","text":"Durere intensă care debutează la 2-3 zile postextracțional."}],"correct":["D","E"],"pages":[589],"source":"set-2"},{"id":"set2-W9e0XVJy","fingerprint":"4350dab574c58504","chapterId":"set-2","subchapterId":"set2-7.08","type":"CS","text":"În ce situație clinică este cel mai frecvent întâlnită osteomielita ca o complicație a alveolitei uscate?","options":[{"id":"A","text":"La pacienți tineri și sănătoși, după extracții necomplicate."},{"id":"B","text":"În zona unghiului mandibular, după extracții laborioase ale molarului de minte inferior."},{"id":"C","text":"După extracții simple ale incisivilor superiori."},{"id":"D","text":"În toate cazurile de alveolită uscată, indiferent de localizare."},{"id":"E","text":"La nivelul tuberozității maxilare, după extracția molarului de minte superior."}],"correct":["B"],"pages":[589],"source":"set-2"},{"id":"set2-ubUDBtDo","fingerprint":"cd037d9e243f66e9","chapterId":"set-2","subchapterId":"set2-7.08","type":"CS","text":"Ce element clinic diferențiază alveolita umedă de alveolita uscată?","options":[{"id":"A","text":"Apariția simptomatologiei la 7-10 zile postextracțional."},{"id":"B","text":"Gingivomucoasa cu aspect normal, neinflamat."},{"id":"C","text":"Pereții osoși alveolari uscați și cu tendință redusă la sângerare."},{"id":"D","text":"Lipsa totală a durerii."},{"id":"E","text":"Prezența unui cheag exuberant, murdar și fetid."}],"correct":["E"],"pages":[589],"source":"set-2"},{"id":"set2-b5wjDdev","fingerprint":"88313973e15c8659","chapterId":"set-2","subchapterId":"set2-7.08","type":"CM","text":"Care sunt componentele corecte ale tratamentului alveolitei umede?","options":[{"id":"A","text":"Avivarea marginilor de gingivomucoasă."},{"id":"B","text":"Păstrarea cheagului exuberant pentru a proteja alveola."},{"id":"C","text":"Administrarea sistematică de antibiotice, indiferent de starea generală a pacientului."},{"id":"D","text":"Administrarea de antialgice și antiinflamatoare nesteroidiene."},{"id":"E","text":"Chiuretajul alveolar și regularizarea planului osos."}],"correct":["A","D","E"],"pages":[589],"source":"set-2"},{"id":"set2-ht_SbrQ3","fingerprint":"d4ad9df6c8c64013","chapterId":"set-2","subchapterId":"set2-7.08","type":"CM","text":"Ce factori pot influența negativ, ducând la o vindecare întârziată a plăgii postextracționale?","options":[{"id":"A","text":"Malnutriția."},{"id":"B","text":"Utilizarea unui lambou de tip \"plic\"."},{"id":"C","text":"Vârsta tânără a pacientului."},{"id":"D","text":"Dehiscența plăgii."},{"id":"E","text":"Radioterapia."}],"correct":["A","D","E"],"pages":[589],"source":"set-2"},{"id":"set2-jtihORUu","fingerprint":"c0a24ff7ccf85f9e","chapterId":"set-2","subchapterId":"set2-7.08","type":"CM","text":"Care dintre următoarele erori de tehnică operatorie pot cauza dehiscența plăgii?","options":[{"id":"A","text":"Sutura în tensiune a lamboului."},{"id":"B","text":"Utilizarea unor ace de mucoasă, rotunde pe secțiune."},{"id":"C","text":"Prezența de spine iritative osoase lăsate pe loc."},{"id":"D","text":"Regularizarea atentă a osului înainte de sutură."},{"id":"E","text":"Repoziționarea unui lambou fără a avea un suport osos subiacent."}],"correct":["A","C","E"],"pages":[589],"source":"set-2"},{"id":"set2-O0w-KxvL","fingerprint":"dcf3d75d1946a96b","chapterId":"set-2","subchapterId":"set2-7.08","type":"CS","text":"Care este principiul de bază în proiectarea unui lambou \"în trapez\" pentru a asigura un aport sanguin suficient și a preveni necroza?","options":[{"id":"A","text":"Marginea liberă a lamboului trebuie să fie mai largă decât baza acestuia."},{"id":"B","text":"Inciziile de eliberare trebuie să fie paralele între ele."},{"id":"C","text":"Lungimea inciziilor de eliberare trebuie să fie egală cu lățimea bazei."},{"id":"D","text":"Baza lamboului trebuie să fie de aceeași lățime ca la un lambou de tip \"plic\"."},{"id":"E","text":"Baza lamboului trebuie să fie mai largă decât marginea liberă."}],"correct":["E"],"pages":[589],"source":"set-2"},{"id":"set2-EQzzuftC","fingerprint":"7c3131c215a4b7fa","chapterId":"set-2","subchapterId":"set2-7.08","type":"CS","text":"Ce manevră este esențială în timpul suturării pentru a minimiza traumatismul lamboului și a evita sfâșierea țesuturilor?","options":[{"id":"A","text":"Folosirea unor ace tăioase pentru o penetrare mai rapidă."},{"id":"B","text":"Inserarea acului perpendicular pe suprafața lamboului."},{"id":"C","text":"Realizarea unor noduri cât mai strânse și apropiate."},{"id":"D","text":"Tracționarea directă a acului prin mucoasă după perforare."},{"id":"E","text":"Utilizarea unui singur nod chirurgical pentru a reduce timpul operator."}],"correct":["B"],"pages":[589],"source":"set-2"},{"id":"set2-fboY2EqQ","fingerprint":"3a9ea6e7803ea03a","chapterId":"set-2","subchapterId":"set2-7.08","type":"CS","text":"Care este intervalul de timp recomandat pentru suprimarea firelor de sutură aplicate la nivelul cavității orale, în condițiile unei evoluții favorabile și necomplicate?","options":[{"id":"A","text":"12-14 zile postoperator"},{"id":"B","text":"3-5 zile postoperator"},{"id":"C","text":"15-17 zile postoperator"},{"id":"D","text":"7-10 zile postoperator"},{"id":"E","text":"5-7 zile postoperator"}],"correct":["D"],"pages":[590],"source":"set-2"},{"id":"set2-SLhebJc3","fingerprint":"d9f2476a3f1e69cd","chapterId":"set-2","subchapterId":"set2-7.08","type":"CM","text":"Care dintre următoarele medicamente sau clase de medicamente pot întârzia procesul de vindecare a unei plăgi postextracționale?","options":[{"id":"A","text":"Citostaticele"},{"id":"B","text":"Stimulează remodelarea colagenului"},{"id":"C","text":"Glucocorticoizii"},{"id":"D","text":"Hormonii de creștere"},{"id":"E","text":"Anticoagulantele"}],"correct":["A","C","E"],"pages":[590],"source":"set-2"},{"id":"set2-ODxjtdp9","fingerprint":"e71eaa1713fbb2fb","chapterId":"set-2","subchapterId":"set2-7.08","type":"CS","text":"Ce substanțe sunt recunoscute pentru efectul lor de a favoriza și grăbi procesul de vindecare?","options":[{"id":"A","text":"Proteinele și carbohidrații"},{"id":"B","text":"Glucocorticoizii și citostaticele"},{"id":"C","text":"Anticoagulantele și antiinflamatoriile steroidiene"},{"id":"D","text":"Stimularea migrării macrofagelor"},{"id":"E","text":"Hormonii de creștere și vitaminele A și C"}],"correct":["E"],"pages":[590],"source":"set-2"},{"id":"set2-e8E1Bx-W","fingerprint":"cccac718603188b1","chapterId":"set-2","subchapterId":"set2-7.08","type":"CS","text":"Care este considerat cel mai important factor implicat în vindecarea întârziată, în special la persoanele în vârstă?","options":[{"id":"A","text":"Radioterapia"},{"id":"B","text":"Vârsta avansată"},{"id":"C","text":"Malnutriția"},{"id":"D","text":"Medicația cronică"},{"id":"E","text":"Depresia imună specifică vârstei"}],"correct":["C"],"pages":[590],"source":"set-2"},{"id":"set2-Y19bL-Hl","fingerprint":"836de37a948f7f54","chapterId":"set-2","subchapterId":"set2-7.08","type":"CM","text":"Care dintre următoarele reprezintă modificări cronice și ireversibile induse de radioterapie la nivelul țesuturilor normale?","options":[{"id":"A","text":"Xerostomia"},{"id":"B","text":"Mucozita"},{"id":"C","text":"Răspunsul imun diminuat"},{"id":"D","text":"Vasculita obliterativă"},{"id":"E","text":"Fibroza"}],"correct":["C","D","E"],"pages":[590],"source":"set-2"},{"id":"set2-KcZ6lnGI","fingerprint":"516a99850bfb1667","chapterId":"set-2","subchapterId":"set2-7.08","type":"CM","text":"Ce mecanisme stau la baza încetinirii vindecării plăgilor în cazul administrării postextracționale de antiinflamatorii steroidiene?","options":[{"id":"A","text":"Inhibiția migrării macrofagelor"},{"id":"B","text":"Stimulează remodelarea colagenului"},{"id":"C","text":"Stimularea migrării macrofagelor"},{"id":"D","text":"Inhibiția remodelării colagenului"},{"id":"E","text":"Stimularea proliferării țesutului de granulație"}],"correct":["A","D","E"],"pages":[590],"source":"set-2"},{"id":"set2-qEYU7vIo","fingerprint":"7e93b948d00bc529","chapterId":"set-2","subchapterId":"set2-7.08","type":"CM","text":"Care sunt factorii care contribuie la vindecarea deficitară a plăgilor la pacienții în vârstă?","options":[{"id":"A","text":"Rata crescută de turn-over a mucoasei orale"},{"id":"B","text":"Depresia imună specifică vârstei"},{"id":"C","text":"Malnutriția"},{"id":"D","text":"Inhibiția migrării macrofagelor"},{"id":"E","text":"Bolile generale asociate"}],"correct":["B","C","E"],"pages":[590],"source":"set-2"},{"id":"set2-W6jOogT3","fingerprint":"f0f7916bb44f380b","chapterId":"set-2","subchapterId":"set2-7.08","type":"CM","text":"Care dintre următorii factori de risc favorizează apariția fracturii radiculare a dintelui de extras?","options":[{"id":"A","text":"Septul interradicular gros și anchiloza dento-alveolară."},{"id":"B","text":"Subminarea coroanei dinților adiacenți prin obturații voluminoase."},{"id":"C","text":"Prezența unor distrucții mari corono-radiculare prin procese carioase."},{"id":"D","text":"Fenomenele de hipercementoză și osul alveolar dens."},{"id":"E","text":"Rădăcinile divergente, în special în cazul primilor molari superiori."}],"correct":["A","D","E"],"pages":[582],"source":"set-2"},{"id":"set2-rXqIYJDu","fingerprint":"cae1d5786577d30c","chapterId":"set-2","subchapterId":"set2-7.08","type":"CM","text":"Care dintre următoarele sunt considerate investigații biologice de rutină obligatorii preextracțional?","options":[{"id":"A","text":"Nivelul transaminazelor serice (ALT, AST)."},{"id":"B","text":"Timpul de sângerare și timpul de coagulare."},{"id":"C","text":"Glicemia sau hemoglobina glicozilată."},{"id":"D","text":"Valoarea INR-ului."},{"id":"E","text":"Ionograma serică completă."}],"correct":["A","C","D"],"pages":[581],"source":"set-2"},{"id":"set2-KuafpWuq","fingerprint":"a995360e299e46b2","chapterId":"set-2","subchapterId":"set2-7.08","type":"CM","text":"Care dintre următoarele erori de tehnică pot determina apariția fracturii coronare a dintelui vecin?","options":[{"id":"A","text":"Utilizarea unui clește de extracție inadecvat, cu fălci prea late."},{"id":"B","text":"Aplicarea forțelor de tracțiune verticală necontrolată asupra cleștelui de extracție."},{"id":"C","text":"Deraparea instrumentarului de extracție în timpul manoperelor chirurgicale."},{"id":"D","text":"Pătrunderea în profunzime cu elevatorul și lezarea sacului folicular."},{"id":"E","text":"Aplicarea defectuoasă a elevatorului, cu punct de sprijin pe dintele vecin."}],"correct":["A","C","E"],"pages":[582],"source":"set-2"},{"id":"set2-kuy3Wk4b","fingerprint":"911ce3fccc9b7260","chapterId":"set-2","subchapterId":"set2-7.08","type":"CS","text":"Care dintre următoarele este accidentul care apare cel mai frecvent în timpul extracției dentare?","options":[{"id":"A","text":"Luxația dintelui vecin."},{"id":"B","text":"Fractura coronară a dintelui de extras."},{"id":"C","text":"Extracția unui alt dinte decât cel de extras."},{"id":"D","text":"Fractura radiculară a dintelui de extras."},{"id":"E","text":"Fractura coronară a dintelui vecin."}],"correct":["B"],"pages":[582],"source":"set-2"},{"id":"set2-lt1OiruO","fingerprint":"e602428da479eca8","chapterId":"set-2","subchapterId":"set2-7.08","type":"CM","text":"Care dintre următoarele măsuri și tehnici contribuie la prevenirea smulgerii sau lezării mugurilor dinților permanenți în timpul extracției molarilor temporari?","options":[{"id":"A","text":"Extracția cu separație radiculară atunci când rădăcinile molarului temporar înconjoară coroana dintelui permanent."},{"id":"B","text":"Evitarea pătrunderii în profunzime cu fălcile cleștelui de extracție sau cu elevatorul."},{"id":"C","text":"Aplicarea fălcilor cleștelui de extracție cât mai profund pe dintele temporar pentru a asigura o priză fermă."},{"id":"D","text":"Pătrunderea în profunzime cu elevatorul pentru luxarea eficientă și rapidă a dintelui temporar."},{"id":"E","text":"Realizarea preextracțional obligatoriu a unei evaluări radiologice pentru a vizualiza raportul cu mugurele subiacent."}],"correct":["A","B","E"],"pages":[582],"source":"set-2"},{"id":"set2-fAoKRWSD","fingerprint":"4cf47e1b88809461","chapterId":"set-2","subchapterId":"set2-7.08","type":"CM","text":"Care sunt atitudinile terapeutice adecvate în managementul leziunilor părților moi perimaxilare survenite în timpul extracției dentare?","options":[{"id":"A","text":"Hemostaza plăgilor limbii cu hemoragii importante din vasele linguale se realizează eficient prin tamponament compresiv."},{"id":"B","text":"În cazul lezării arterei palatine, cu hemoragie în jet, vasul se ligaturează distal de plagă."},{"id":"C","text":"Fragmentele mici, devitale, de la nivelul plăgilor gingivale liniare vor fi repoziționate și suturate pentru a conserva țesutul."},{"id":"D","text":"Plăgile gingivale liniare cu lambouri viabile necesită suturarea plăgii."},{"id":"E","text":"Osul alveolar descoperit parțial, care nu poate fi reacoperit prin sutură, necesită protejare cu o meșă iodoformată."}],"correct":["B","D","E"],"pages":[583],"source":"set-2"},{"id":"set2-bJWP6TnD","fingerprint":"27a19750167d19d6","chapterId":"set-2","subchapterId":"set2-7.08","type":"CS","text":"Care este principala măsură hemostatică indicată în cazul plăgilor limbii însoțite de hemoragii importante, apărute prin deraparea elevatoarelor în timpul extracției molarilor inferiori?","options":[{"id":"A","text":"Sutura în masă a plăgii."},{"id":"B","text":"Ligaturarea vasului sângerând proximal de plagă."},{"id":"C","text":"Aplicarea unei meșe iodoformate în focarul hemoragic."},{"id":"D","text":"Tamponamentul compresiv al plăgii pentru asigurarea rapidă a hemostazei."},{"id":"E","text":"Excizia marginilor zdrobite și lăsarea plăgii deschise pentru drenaj."}],"correct":["A"],"pages":[583],"source":"set-2"},{"id":"set2-XfGPFt9P","fingerprint":"5e4b2d42e9880dbf","chapterId":"set-2","subchapterId":"set2-7.08","type":"CM","text":"Care sunt caracteristicile și complicațiile asociate plăgilor planșeului bucal produse în timpul extracției dentare?","options":[{"id":"A","text":"Tratamentul se realizează exclusiv în cabinetul stomatologic prin ligaturarea vaselor lezate."},{"id":"B","text":"Prezintă un risc major de asfixie prin obstrucția căilor aeriene superioare."},{"id":"C","text":"Sunt produse în mod obișnuit prin aplicarea incorectă a cleștelui peste mucoasă."},{"id":"D","text":"Pot fi însoțite de hemoragii masive, cu apariția ulterioară de hematoame disecante."},{"id":"E","text":"Suprainfectarea hematomului disecant reprezintă o complicație ulterioară posibilă."}],"correct":["B","D","E"],"pages":[583],"source":"set-2"},{"id":"set2-a48nVSY0","fingerprint":"8d521b775cc14860","chapterId":"set-2","subchapterId":"set2-7.08","type":"CS","text":"Care este atitudinea terapeutică recomandată în situația lezării arterei palatine, manifestată printr-o hemoragie în jet în timpul extracției molarilor superiori?","options":[{"id":"A","text":"Ligaturarea vasului proximal de plagă."},{"id":"B","text":"Protejarea zonei mucozale expuse cu o meșă iodoformată."},{"id":"C","text":"Realizarea hemostazei prin tamponament prelungit al bolții palatine."},{"id":"D","text":"Ligaturarea vasului distal de plagă."},{"id":"E","text":"Suturarea în masă a mucoasei palatine."}],"correct":["D"],"pages":[583],"source":"set-2"},{"id":"set2-ou2w8HNt","fingerprint":"a3d56a06cd1d1ebb","chapterId":"set-2","subchapterId":"set2-7.08","type":"CM","text":"Care dintre următoarele afirmații descriu corect mecanismele de producere și conduita în leziunile părților moi perimaxilare post-extracționale?","options":[{"id":"A","text":"În plăgile întinse cu decolări osoase importante, osul alveolar este descoperit parțial, iar marginile mucozale sunt dilacerate și zdrobite."},{"id":"B","text":"Lezarea părților moi din cavitatea orală rezultă aproape întotdeauna din folosirea unor forțe excesive, necontrolate."},{"id":"C","text":"Plăgile palatine apar cel mai frecvent prin înțeparea mucoasei în timpul extracției molarilor inferiori."},{"id":"D","text":"În cazul plăgilor întinse, dacă osul alveolar descoperit nu poate fi reacoperit prin sutură, porțiunea expusă se excizează chirurgical."},{"id":"E","text":"Plăgile gingivale liniare se pot produce prin deraparea elevatorului în timpul manoperelor chirurgicale."}],"correct":["A","B","E"],"pages":[583],"source":"set-2"},{"id":"set2-LoNYyG_M","fingerprint":"e2a6a37c7c4d087a","chapterId":"set-2","subchapterId":"set2-7.08","type":"CM","text":"Care sunt zonele anatomice recunoscute pentru o corticală subțire, favorizând apariția frecventă a fracturii corticalei alveolare în timpul extracțiilor dentare?","options":[{"id":"A","text":"Corticala palatinală din dreptul molarilor superiori."},{"id":"B","text":"Corticala vestibulară de la nivelul grupului frontal inferior."},{"id":"C","text":"Corticala vestibulară de la nivelul caninului superior și al molarilor superiori."},{"id":"D","text":"Podeaua sinusului maxilar."},{"id":"E","text":"Corticala vestibulară de la nivelul molarilor inferiori."}],"correct":["B","C","D"],"pages":[583],"source":"set-2"},{"id":"set2-FCm0IRbB","fingerprint":"7d0fbc33b3e035aa","chapterId":"set-2","subchapterId":"set2-7.08","type":"CS","text":"Care este atitudinea terapeutică recomandată în situația în care, pe parcursul extracției, se constată că dintele și țesutul osos al tuberozității maxilare formează corp comun?","options":[{"id":"A","text":"Extracția forțată a dintelui cu elevatorul drept urmată de repoziționarea exclusivă a fragmentului osos."},{"id":"B","text":"Reașezarea tuberozității împreună cu dintele extras, monitorizare 6-8 săptămâni, urmată de extracția molarului prin alveolotomie."},{"id":"C","text":"Menținerea permanentă a dintelui în alveolă, renunțându-se definitiv la indicația de extracție."},{"id":"D","text":"Practicarea imediată a curei radicale de sinus maxilar pentru a preveni dezvoltarea unei sinuzite."},{"id":"E","text":"Îndepărtarea completă a fragmentului osos și sutura primară imediată a mucoasei acoperitoare."}],"correct":["B"],"pages":[584],"source":"set-2"},{"id":"set2-gK-l8TGQ","fingerprint":"fe4e75add3912001","chapterId":"set-2","subchapterId":"set2-7.08","type":"CM","text":"Ce incidente se pot asocia cu fractura corticalei linguale survenită în timpul extracției molarilor inferiori?","options":[{"id":"A","text":"Împingerea dintelui în planșeul oral."},{"id":"B","text":"Lezarea plexului venos perituberozitar."},{"id":"C","text":"Formarea unei comunicări oro-sinusale largi."},{"id":"D","text":"Împingerea dintelui în podeaua sinusului maxilar."},{"id":"E","text":"Lezarea nervului lingual."}],"correct":["A","E"],"pages":[583],"source":"set-2"},{"id":"set2-5iv_6Ghi","fingerprint":"8693829d0a618aa1","chapterId":"set-2","subchapterId":"set2-7.08","type":"CM","text":"Care sunt etapele terapeutice indicate în mod specific pentru tratamentul unei fracturi complete a procesului alveolar, în care fragmentul osos este complet detașat de periost?","options":[{"id":"A","text":"Regularizarea marginilor osoase restante."},{"id":"B","text":"Repoziționarea fragmentului osos fracturat."},{"id":"C","text":"Suturarea plăgii mucozale."},{"id":"D","text":"Aplicarea unui plasture hemostatic pentru reintegrarea osoasă a fragmentului deperiostat."},{"id":"E","text":"Îndepărtarea fragmentului osos din plagă."}],"correct":["A","C","E"],"pages":[583],"source":"set-2"},{"id":"set2-nZR3WvGr","fingerprint":"595a2d312871f672","chapterId":"set-2","subchapterId":"set2-7.08","type":"CM","text":"Ce consecințe și riscuri anatomo-clinice sunt direct provocate de producerea fracturii tuberozității maxilare?","options":[{"id":"A","text":"Secționarea nervului alveolar inferior prin aplicarea cleștelui de extracție."},{"id":"B","text":"Apariția unui hematom cu risc ridicat de infecție din cauza florei orale mixte."},{"id":"C","text":"Producerea unor comunicări oro-sinusale largi, mai ales la smulgerea tuberozității."},{"id":"D","text":"Apariția unei hemoragii importante prin lezarea plexului venos perituberozitar."},{"id":"E","text":"Împingerea accidentală a molarului de minte superior în planșeul oral."}],"correct":["B","C","D"],"pages":[584],"source":"set-2"},{"id":"set2-kD8dJ5Us","fingerprint":"ca1e65cba55524a0","chapterId":"set-2","subchapterId":"set2-7.08","type":"CM","text":"Care sunt factorii de risc asociați cu producerea fracturii de mandibulă în timpul extracției dentare?","options":[{"id":"A","text":"Atrofia accentuată a maxilarului superior."},{"id":"B","text":"Procesele resorbtive periradiculare de la nivelul premolarilor."},{"id":"C","text":"Prezența unui chist folicular la nivelul mandibulei."},{"id":"D","text":"Atrofia accentuată a mandibulei."},{"id":"E","text":"Incluzia profundă a molarului de minte inferior."}],"correct":["C","D","E"],"pages":[584,585],"source":"set-2"},{"id":"set2-YNtndoRY","fingerprint":"d2161bd17b610dd9","chapterId":"set-2","subchapterId":"set2-7.08","type":"CS","text":"Care este situația clinică în care folosirea elevatorului Lecluse prezintă o contraindicație specifică din cauza riscului de a produce o fractură de unghi mandibular?","options":[{"id":"A","text":"Extracția unui molar de minte inferior cu rădăcini drepte."},{"id":"B","text":"Odontectomia unui molar de minte superior inclus profund în tuberozitatea maxilară."},{"id":"C","text":"Odontectomia molarilor de minte superiori situați în imediata vecinătate a sinusului maxilar."},{"id":"D","text":"Extracția premolarilor mandibulari cu procese patologice periapicale majore."},{"id":"E","text":"Extracția unui molar de minte inferior cu rădăcini puternic divergente și curbe."}],"correct":["A"],"pages":[584,585],"source":"set-2"},{"id":"set2-QpIZ00Xk","fingerprint":"cc0fa154f6287d3e","chapterId":"set-2","subchapterId":"set2-7.08","type":"CM","text":"Ce aspecte anatomice și clinice sunt asociate cu accidentul de împingere a molarului de minte superior în spațiul pterigomaxilar?","options":[{"id":"A","text":"Rezolvarea imediată a accidentului este adesea împiedicată de hemoragia rezultată prin lezarea venei jugulare interne."},{"id":"B","text":"Tulburările de deschidere a cavității orale apar atunci când dintele se situează imediat medial de ramul mandibular."},{"id":"C","text":"Dintele este situat între lama laterală pterigoidiană și mușchiul pterigoidian extern."},{"id":"D","text":"Pătrunderea resturilor dentare în fosa infratemporală implică riscul apariției flegmonului hemifacial."},{"id":"E","text":"Accidentul se produce exclusiv în prezența unor procese resorbtive periradiculare majore."}],"correct":["B","C","D"],"pages":[584,585],"source":"set-2"},{"id":"set2-ox_bqoOl","fingerprint":"ecb440fa3c1e2e19","chapterId":"set-2","subchapterId":"set2-7.08","type":"CS","text":"Care este abordul chirurgical indicat pentru îndepărtarea unui molar de minte inferior împins în planșeul bucal, în situația în care dintele este localizat sub mușchiul milohioidian?","options":[{"id":"A","text":"Abordul pe cale cutanată."},{"id":"B","text":"Abordul pe cale orală."},{"id":"C","text":"Abordul prin fosa infratemporală."},{"id":"D","text":"Abordul pe cale transalveolară directă prin alveola dintelui extras."},{"id":"E","text":"Abordul transsinusal."}],"correct":["A"],"pages":[584,585],"source":"set-2"},{"id":"set2-h2qWN3sk","fingerprint":"c442773ada627174","chapterId":"set-2","subchapterId":"set2-7.08","type":"CM","text":"Care sunt caracteristicile procedurii de navigație chirurgicală utilizate pentru localizarea dinților împinși în spațiile perimaxilare?","options":[{"id":"A","text":"Presupune obligatoriu vizualizarea directă cu ajutorul unui microscop chirurgical pe toată durata procedurii."},{"id":"B","text":"Localizarea tridimensională intraoperatorie utilizează un sistem computerizat pe bază de raze infraroșii sau unde electromagnetice."},{"id":"C","text":"Se bazează pe realizarea unui model virtual al regiunii obținut printr-un examen CT preoperator."},{"id":"D","text":"Permite reducerea timpului de intervenție și a riscului de lezare a unor structuri anatomice prin limitarea manevrelor de explorare."},{"id":"E","text":"Impune efectuarea unei tomografii prin rezonanță magnetică intraoperatorie pentru ghidarea în timp real a instrumentarului."}],"correct":["B","C","D"],"pages":[584,585],"source":"set-2"},{"id":"set2-8qjApcyW","fingerprint":"b9b3fa9d046df897","chapterId":"set-2","subchapterId":"set2-7.08","type":"CM","text":"Care dintre următoarele afirmații referitoare la recuperarea funcțională a structurilor nervoase lezate în urma extracției dentare sunt adevărate?","options":[{"id":"A","text":"După o perioadă de 2 ani, probabilitatea unei recuperări spontane a nervului alveolar inferior rămâne foarte ridicată."},{"id":"B","text":"Recuperarea funcțională a nervului alveolar inferior apare frecvent la 6-9 luni, putând ajunge uneori la 18 luni."},{"id":"C","text":"Tulburările se remit în timp pentru 87% dintre pacienții cu leziuni ale nervului alveolar inferior."},{"id":"D","text":"Secționarea nervului mentonier determină instalarea unei anestezii definitive."},{"id":"E","text":"Sensibilitatea nervului mentonier afectat prin tracțiunea exagerată a lamboului revine în decurs de câteva săptămâni."}],"correct":["B","D","E"],"pages":[585,586],"source":"set-2"},{"id":"set2-MynTJ_A6","fingerprint":"6d71e4703f7eb6cc","chapterId":"set-2","subchapterId":"set2-7.08","type":"CM","text":"Ce măsuri tehnice sunt recomandate în timpul extracției molarilor inferiori pentru a reduce incidența lezării nervului lingual?","options":[{"id":"A","text":"Evitarea rezecției corticalei linguale."},{"id":"B","text":"Chiuretajul viguros al sacului folicular al molarului de minte de pe versantul lingual al alveolei."},{"id":"C","text":"Secționarea dintelui, atunci când situația o impune, pentru a facilita extracția."},{"id":"D","text":"Realizarea trepanării osoase cu predilecție la nivelul corticalei osoase vestibulare."},{"id":"E","text":"Plasarea profundă a suturilor în lamboul lingual pentru o ancorare optimă a marginilor plăgii."}],"correct":["A","C","D"],"pages":[585,586],"source":"set-2"},{"id":"set2-DVFVhbAq","fingerprint":"e0efa1b7383b99e0","chapterId":"set-2","subchapterId":"set2-7.08","type":"CS","text":"Care este argumentul principal ce justifică rata mai mare de recuperare funcțională a nervului alveolar inferior comparativ cu nervul lingual, în urma lezării pe parcursul extracțiilor dentare?","options":[{"id":"A","text":"Nervul alveolar inferior se află în contact direct cu periostul pe fața linguală a mandibulei."},{"id":"B","text":"Nervul alveolar inferior are o zonă de inervație senzitivă mult mai redusă."},{"id":"C","text":"Nervul alveolar inferior nu este expus tracțiunii lamboului creat pentru extracția premolarilor inferiori."},{"id":"D","text":"Nervul alveolar inferior traversează trigonul retromolar, fiind ferit de acțiunea instrumentarului rotativ."},{"id":"E","text":"Nervul alveolar inferior este reținut în interiorul unui canal osos, facilitând contactul direct al terminațiilor nervului afectat."}],"correct":["E"],"pages":[585,586],"source":"set-2"},{"id":"set2-8r4f6oNn","fingerprint":"0065b8e60d21d07b","chapterId":"set-2","subchapterId":"set2-7.08","type":"CM","text":"Care sunt caracteristicile accidentelor și complicațiilor ce pot surveni în timpul extracției dentare?","options":[{"id":"A","text":"Riscul de aspirare a fragmentelor dentare este mai crescut în situația în care poziția pacientului în fotoliu se apropie de clinostatism."},{"id":"B","text":"Lipsa unui sprijin corect al mandibulei în timpul extracției molarilor inferiori determină durere intensă în articulația temporomandibulară și imposibilitatea închiderii cavității orale."},{"id":"C","text":"Secționarea nervului nazopalatin determină sechele permanente cu alterarea funcției masticatorii."},{"id":"D","text":"Instrumentele fracturate reținute în spațiul parodontal vizibile exclusiv radiologic impun un tratament diferit de cel pentru pătrunderea apexurilor în spațiile învecinate."},{"id":"E","text":"Lezarea nervului lingual apare cu o frecvență de 1% din cazurile de extracție a molarului de minte."}],"correct":["A","B","E"],"pages":[585,586],"source":"set-2"},{"id":"set2-5Ano6KOz","fingerprint":"aee907d3c6df39dd","chapterId":"set-2","subchapterId":"set2-7.08","type":"CS","text":"Ce trăsătură diferențiază lezarea nervului lingual de cea a nervului alveolar inferior, ca urmare a complicațiilor extracției dentare?","options":[{"id":"A","text":"Lezarea nervului lingual prezintă o probabilitate mult mai crescută de recuperare spontană."},{"id":"B","text":"Rata de apariție a lezării nervului lingual este semnificativ mai mare comparativ cu cea a nervului alveolar inferior în timpul odontectomiei molarului de minte."},{"id":"C","text":"Pacienții cu leziuni ale nervului lingual acuză modificări gustative, aspect ce le agravează disconfortul."},{"id":"D","text":"Nervul lingual beneficiază de un grad înalt de regenerare prin dispunerea sa într-un canal osos."},{"id":"E","text":"Lezarea nervului lingual este evaluată orientativ exclusiv prin radiografii retrodentare sau ortopantomografii."}],"correct":["C"],"pages":[585,586],"source":"set-2"},{"id":"set2-PsDWQfr8","fingerprint":"ad8ad0239c7be62c","chapterId":"set-2","subchapterId":"set2-7.08","type":"CM","text":"Care sunt afirmațiile adevărate privind clasificarea și manifestarea hemoragiei postextracționale în funcție de momentul apariției?","options":[{"id":"A","text":"Hemoragia imediat-prelungită este definită de continuarea sângerării peste perioada normală de formare a cheagului, fără tendință de oprire spontană."},{"id":"B","text":"Hemoragia precoce se caracterizează prin reapariția sângerării la 2-3 ore de la extracție."},{"id":"C","text":"Oprirea normală a sângerării unei plăgi postextracționale se realizează în 15-20 de minute, prin formarea cheagului sangvin."},{"id":"D","text":"Sângerarea postextracțională constituie o tulburare severă de hemostază de fiecare dată când persistă în primele 12-24 de ore."},{"id":"E","text":"Hemoragia tardivă se declanșează, de regulă, la 12-24 de ore de la momentul extracției dentare."}],"correct":["A","B","C"],"pages":[586],"source":"set-2"},{"id":"set2-60SDIn-3","fingerprint":"875b56be327850b5","chapterId":"set-2","subchapterId":"set2-7.08","type":"CM","text":"Care dintre următoarele clase de medicamente sau substanțe sunt incluse în grupul celor 5 „A” recunoscute pentru influențarea hemostazei postextracționale?","options":[{"id":"A","text":"Antitumoralele (citostaticele)"},{"id":"B","text":"Antibioticele"},{"id":"C","text":"Antidepresivele"},{"id":"D","text":"Anticoagulantele"},{"id":"E","text":"Antiinflamatoarele nesteroidiene (AINS)"}],"correct":["A","B","D"],"pages":[587],"source":"set-2"},{"id":"set2-oaMPw3X2","fingerprint":"f172ac9e67bd35e3","chapterId":"set-2","subchapterId":"set2-7.08","type":"CM","text":"Care dintre următoarele afirmații descriu corect tratamentul local și agenții utilizați în abordarea hemoragiei postextracționale?","options":[{"id":"A","text":"Produsele pe bază de colagen și celuloza oxidată sunt clasificate ca agenți hemostatici pasivi."},{"id":"B","text":"Electrocoagularea țesuturilor sângerânde previne garantat necroza tisulară și reprezintă o metodă de elecție în oprirea definitivă a hemoragiei."},{"id":"C","text":"Pulberea uscată de trombină se dizolvă în ser fiziologic steril și se injectează cu presiune ridicată intraalveolar."},{"id":"D","text":"Utilizarea soluției de acid tranexamic 5% este contraindicată în situațiile în care nervul alveolar inferior sau nervul mentonier sunt expuși."},{"id":"E","text":"Acidul aminocaproic în soluție 5% se utilizează prin imbibiția unei meșe sterile, care se aplică sub presiune fermă (compresiv) intraalveolar."}],"correct":["A","D"],"pages":[588],"source":"set-2"},{"id":"set2-OV1chgMD","fingerprint":"1dbb88d30b657b4b","chapterId":"set-2","subchapterId":"set2-7.08","type":"CM","text":"În contextul tratamentului general al hemoragiilor postextracționale, administrarea de etamsilat prezintă următoarele proprietăți farmacodinamice și posologice:","options":[{"id":"A","text":"Determină creșterea rezistenței capilare."},{"id":"B","text":"Acționează exclusiv asupra hemostazei primare, prin favorizarea adezivității trombocitare."},{"id":"C","text":"Stimulează factorii plasmatici ai coagulării, fiind indicat în deficitele majore ale acestora."},{"id":"D","text":"Se poate administra intramuscular, utilizând 1-2 fiole de 2 ml dintr-o soluție de 12,5%."},{"id":"E","text":"Intervine direct asupra procesului de fibrinoliză, prelungind stabilitatea cheagului."}],"correct":["A","B","D"],"pages":[588],"source":"set-2"},{"id":"set2-Wtgh7Wx4","fingerprint":"f8c69a8e7192945d","chapterId":"set-2","subchapterId":"set2-7.08","type":"CM","text":"Care dintre următorii reprezintă factori locali implicați în declanșarea hemoragiilor postextracționale?","options":[{"id":"A","text":"Vasodilatația secundară survenită în cazul anesteziilor plexale în care se utilizează vasoconstrictor."},{"id":"B","text":"Lezarea accidentală a unor structuri vasculare, precum artera alveolară inferioară."},{"id":"C","text":"Lipsa clătirii cavității orale cu apă imediat după extracția dentară."},{"id":"D","text":"Prezența eschilelor osoase, a resturilor dentare sau a proeminențelor osoase la nivelul alveolei."},{"id":"E","text":"Trombocitopatiile și coagulopatiile congenitale sau dobândite."}],"correct":["A","B","D"],"pages":[586],"source":"set-2"},{"id":"set2-YHxCAOHR","fingerprint":"445ca080f112cf59","chapterId":"set-2","subchapterId":"set2-7.08","type":"CS","text":"Trismusul apărut în urma extracțiilor traumatice sau a odontectomiei molarilor de minte inferiori este determinat de:","options":[{"id":"A","text":"O contracție spastică a mușchiului pterigoidian intern cauzată de iritația inflamatorie."},{"id":"B","text":"Lezarea ireversibilă a ramurilor nervoase motorii de la nivelul cavității bucale."},{"id":"C","text":"Tracțiunea exagerată a lambourilor cu depărtătoarele pe parcursul intervenției."},{"id":"D","text":"Administrarea anestezicelor plexale formulate cu o concentrație mare de vasoconstrictor."},{"id":"E","text":"O reacție de fibroză permanentă instalată rapid la nivelul mușchilor maseteri."}],"correct":["A"],"pages":[586],"source":"set-2"},{"id":"set2-PtCpLxvy","fingerprint":"fcc34dab576fc4d1","chapterId":"set-2","subchapterId":"set2-7.08","type":"CS","text":"Care este atitudinea terapeutică de elecție în cazul pacienților diagnosticați cu tulburări ale hemostazei (hemofilia A, hemofilia B, boala von Willebrand) care necesită o extracție dentară?","options":[{"id":"A","text":"Hemostaza va fi asigurată exclusiv prin administrarea profilactică a unei cure de antibiotice cu spectru larg."},{"id":"B","text":"Se va recurge la întreruperea bruscă a oricărui tratament anticoagulant concomitent, fără a solicita un consult interdisciplinar."},{"id":"C","text":"Intervenția trebuie temporizată nedefinit până la remiterea completă și spontană a afecțiunii hematologice de bază."},{"id":"D","text":"Extracția se poate realiza în ambulatoriu, fiind suficientă aplicarea unui pansament supraalveolar compresiv îmbibat cu acid tranexamic."},{"id":"E","text":"Extracțiile se vor realiza obligatoriu în secțiile de chirurgie oro-maxilo-facială, strict în condiții de spitalizare."}],"correct":["E"],"pages":[588],"source":"set-2"},{"id":"set2-DFKHzumD","fingerprint":"902a355fffb2029b","chapterId":"set-2","subchapterId":"set2-7.08","type":"CM","text":"Care sunt factorii care favorizează apariția alveolitei ca o complicație specifică extracției dentare?","options":[{"id":"A","text":"Tulburările vasomotorii regionale induse de acțiunea vasoconstrictoarelor utilizate."},{"id":"B","text":"Persistența unor eschile osoase sau a unor fragmente dentare în alveolă."},{"id":"C","text":"Activitatea fibrinolitică scăzută determinată de prezența florei orale saprofite."},{"id":"D","text":"Menținerea pe termen scurt a unui pansament lax la nivel intraalveolar."},{"id":"E","text":"Aplicarea intraalveolară a unor substanțe cu rol antiseptic sau hemostatic care interferă cu organizarea cheagului."}],"correct":["A","B","E"],"pages":[588],"source":"set-2"},{"id":"set2-LiX6h5NS","fingerprint":"3a4d2c1e90c1b108","chapterId":"set-2","subchapterId":"set2-7.08","type":"CS","text":"Care este tabloul clinic și evolutiv caracteristic alveolitei uscate postextracționale?","options":[{"id":"A","text":"Durere intensă apărută la 2-3 zile postextracțional, ameliorată doar parțial prin medicația antalgică uzuală."},{"id":"B","text":"Sângerare abundentă a pereților osoși la inspecția cavității intraalveolare."},{"id":"C","text":"Apariția rapidă a primelor semne de vindecare, în primele 48 de ore sub tratament local adecvat."},{"id":"D","text":"Durere moderată însoțită de prezența unui cheag exuberant, de aspect fetid și suprainfectat."},{"id":"E","text":"Prezența unei adenopatii satelite însoțită constant de semne generale de infecție sistemică."}],"correct":["A"],"pages":[589],"source":"set-2"},{"id":"set2-dJr9W4Zz","fingerprint":"2784452d369fe499","chapterId":"set-2","subchapterId":"set2-7.08","type":"CM","text":"Ce semne clinice și anatomo-patologice pot fi evidențiate la examinarea locală în cazul alveolitei umede?","options":[{"id":"A","text":"Acumularea unui exces de țesut de granulație la nivelul alveolei postextracționale."},{"id":"B","text":"Gingivomucoasa adiacentă prezintă un aspect aton la inspecție."},{"id":"C","text":"Gingivomucoasa este inflamată și congestionată după îndepărtarea cheagului."},{"id":"D","text":"Lipsa totală a oricărui tip de cheag, cu expunerea directă a osului subiacent."},{"id":"E","text":"La palpare, pereții osoși prezintă un caracter moale, osteitic."}],"correct":["A","C","E"],"pages":[589],"source":"set-2"},{"id":"set2-DZyqAPuR","fingerprint":"bcd997bcaf70c1e6","chapterId":"set-2","subchapterId":"set2-7.08","type":"CS","text":"Care este principalul mecanism patologic implicat în apariția alveolitei uscate?","options":[{"id":"A","text":"Formarea unui polip gingival datorat acumulării de țesut de granulație în exces."},{"id":"B","text":"Suprainfectarea unui cheag exuberant care determină o reacție febrilă sistemică la pacienții imunodeprimați."},{"id":"C","text":"Necroza pereților osoși în urma administrării profilactice de antibiotice sistemice postextracțional."},{"id":"D","text":"Liza cheagului datorată acțiunii fibrinolitice inițiate de osul alveolar, asociată cu flora saprofită."},{"id":"E","text":"Transformarea florei bacteriene saprofite în floră patogenă specifică sub acțiunea directă a vasoconstrictoarelor."}],"correct":["D"],"pages":[588],"source":"set-2"},{"id":"set2-_xDiiIyw","fingerprint":"9d6b3c5251bb1b4c","chapterId":"set-2","subchapterId":"set2-7.08","type":"CM","text":"Ce măsuri terapeutice și profilactice sunt indicate în managementul formelor de alveolită postextracțională?","options":[{"id":"A","text":"Conduita locală în alveolita umedă implică chiuretajul alveolar urmat de regularizarea planului osos."},{"id":"B","text":"Tratamentul biostimulator specific în alveolita uscată asigură apariția primelor semne de vindecare în primele 48 de ore."},{"id":"C","text":"Administrarea profilactică a antibioterapiei sistemice în toate cazurile de alveolită umedă."},{"id":"D","text":"Tratamentul alveolitei uscate include irigații ale alveolei cu soluții slab antiseptice și chiuretaj alveolar."},{"id":"E","text":"Introducerea gelului cu clorhexidină 0,2% sau a fibrinei îmbogățite cu trombocite în plagă reduce incidența afecțiunii."}],"correct":["A","D","E"],"pages":[589],"source":"set-2"},{"id":"set2-7zBqFj_G","fingerprint":"87cb564891219beb","chapterId":"set-2","subchapterId":"set2-7.08","type":"CM","text":"Care sunt afirmațiile adevărate privind managementul chirurgical al lambourilor și prevenirea dehiscenței plăgii postextracționale?","options":[{"id":"A","text":"Repoziționarea și suturarea unui lambou fără suport osos subiacent determină apariția dehiscenței."},{"id":"B","text":"Pentru sutură se recomandă utilizarea acelor de mucoasă cu secțiune triunghiulară, inserate oblic."},{"id":"C","text":"Lamboul în trapez necesită o bază mai largă decât marginea liberă pentru a evita necroza."},{"id":"D","text":"Lambourile „plic” prezintă un risc crescut de ischemie din cauza bazei întrerupte de incizii."},{"id":"E","text":"Firele de sutură se suprimă la 14-21 de zile postoperator în cazul unei evoluții fără complicații."}],"correct":["A","C"],"pages":[589],"source":"set-2"},{"id":"set2-nYmsvBaX","fingerprint":"8c0da96b061d0fad","chapterId":"set-2","subchapterId":"set2-7.08","type":"CM","text":"Care sunt mecanismele prin care administrarea postextracțională de antiinflamatorii steroidiene încetinește vindecarea plăgii?","options":[{"id":"A","text":"Stimularea migrației macrofagelor spre focarul inflamator."},{"id":"B","text":"Stimularea proliferării țesutului de granulație."},{"id":"C","text":"Inhibiția remodelării colagenului."},{"id":"D","text":"Inhibarea proliferării țesutului de granulație."},{"id":"E","text":"Inhibiția migrării macrofagelor."}],"correct":["B","C","E"],"pages":[590],"source":"set-2"},{"id":"set2-HE9i0aqe","fingerprint":"b3023cb84dd62fa9","chapterId":"set-2","subchapterId":"set2-7.08","type":"CM","text":"Care dintre următoarele reprezintă modificări cronice, ireversibile, provocate de radioterapie la nivelul țesuturilor orale?","options":[{"id":"A","text":"Mucozita"},{"id":"B","text":"Fibroza"},{"id":"C","text":"Răspunsul imun diminuat"},{"id":"D","text":"Vasculita obliterativă"},{"id":"E","text":"Xerostomia"}],"correct":["B","C","D"],"pages":[590],"source":"set-2"},{"id":"set2-ZeUPLvnx","fingerprint":"0c205b5ad7c54296","chapterId":"set-2","subchapterId":"set2-7.08","type":"CM","text":"Care sunt erorile de tehnică operatorie ce favorizează ischemia locală sau apariția dehiscenței la nivelul plăgii postextracționale?","options":[{"id":"A","text":"Neînlăturarea spinelor iritative osoase înainte de sutură."},{"id":"B","text":"Sutura în tensiune a lamboului."},{"id":"C","text":"Realizarea unor noduri de sutură prea strânse sau prea apropiate."},{"id":"D","text":"Plasarea unui suport osos subiacent solid pentru lamboul repoziționat."},{"id":"E","text":"Inserarea perpendiculară pe mucoasă a acelor rotunde pe secțiune."}],"correct":["A","B","C"],"pages":[589],"source":"set-2"},{"id":"set2-WdT3r5YO","fingerprint":"6d7d66da2d968ef0","chapterId":"set-2","subchapterId":"set2-7.08","type":"CS","text":"Care este cel mai important factor implicat în vindecarea întârziată a plăgilor, cu incidență deosebită la pacienții vârstnici?","options":[{"id":"A","text":"Carența izolată de vitamina C"},{"id":"B","text":"Malnutriția"},{"id":"C","text":"Xerostomia cronică"},{"id":"D","text":"Depresia imună determinată de citostatice"},{"id":"E","text":"Medicația anticoagulantă"}],"correct":["B"],"pages":[590],"source":"set-2"}];
